WITH with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT customer_id, MIN(started_at) AS started_at, SUM(island_id) AS total_island_id FROM islands GROUP BY CUBE (customer_id)
